import React, { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import axios from 'axios';
import { useAuth } from '../context/AuthContext';

const Profile = () => {
    const { user, logOut } = useAuth();
    const navigate = useNavigate();
    const [orders, setOrders] = useState([]);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        const fetchOrders = async () => {
            if (!user) return;
            try {
                const token = await user.getIdToken();
                const { data } = await axios.get('http://localhost:5001/api/orders/my-orders', {
                    headers: { Authorization: `Bearer ${token}` }
                });
                setOrders(data);
            } catch (err) {
                console.error("Error fetching orders:", err);
            } finally {
                setLoading(false);
            }
        };

        fetchOrders();
    }, [user]);

    const getStatusColor = (status) => {
        switch (status) {
            case 'Delivered': return 'text-emerald-600 bg-emerald-50 border-emerald-100';
            case 'Shipped': return 'text-blue-600 bg-blue-50 border-blue-100';
            case 'Processing': return 'text-amber-600 bg-amber-50 border-amber-100';
            default: return 'text-slate-500 bg-slate-50 border-slate-100';
        }
    };

    const getStatusStep = (status) => {
        const steps = ['Pending', 'Processing', 'Shipped', 'Delivered'];
        return steps.indexOf(status);
    };

    if (!user) {
        return (
            <div className="min-h-screen flex items-center justify-center bg-white font-['Work_Sans']">
                <div className="text-center">
                    <p className="text-slate-400 uppercase tracking-widest text-xs font-bold mb-4">Identification Required</p>
                    <button onClick={() => navigate('/')} className="px-8 py-3 bg-[#10221c] text-white text-xs font-bold uppercase tracking-widest rounded-sm hover:bg-black transition-all">Go Home</button>
                </div>
            </div>
        );
    }

    return (
        <div className="bg-[#fafafa] min-h-screen font-['Work_Sans']">
            <main className="max-w-6xl mx-auto px-6 py-16">
                <div className="grid grid-cols-1 lg:grid-cols-4 gap-12">

                    {/* Sidebar / Profile Header */}
                    <aside className="lg:col-span-1 border-r border-slate-100 pr-8">
                        <div className="sticky top-28 space-y-8">
                            <div className="space-y-4">
                                <div className="w-20 h-20 bg-slate-200 rounded-full overflow-hidden border-2 border-white shadow-sm">
                                    {user.photoURL ? (
                                        <img src={user.photoURL} alt="User" className="w-full h-full object-cover" />
                                    ) : (
                                        <div className="w-full h-full flex items-center justify-center bg-[#10221c] text-white font-bold text-2xl">
                                            {user.displayName?.[0] || user.email?.[0]}
                                        </div>
                                    )}
                                </div>
                                <div>
                                    <h1 className="text-xl font-bold text-[#10221c] tracking-tight">{user.displayName || "Value Member"}</h1>
                                    <p className="text-xs text-slate-400 font-medium">{user.email}</p>
                                </div>
                            </div>

                            <nav className="space-y-1">
                                <button className="w-full text-left px-4 py-2 text-xs font-bold uppercase tracking-widest bg-[#10221c] text-white rounded-sm">Acquisitions</button>
                                <button className="w-full text-left px-4 py-2 text-xs font-bold uppercase tracking-widest text-slate-400 hover:text-[#10221c] hover:bg-slate-50 transition-all">Account Settings</button>
                                <button className="w-full text-left px-4 py-2 text-xs font-bold uppercase tracking-widest text-slate-400 hover:text-[#10221c] hover:bg-slate-50 transition-all">Luxury Concierge</button>
                            </nav>

                            <button 
                                onClick={() => window.confirm("Terminate session?") && logOut()}
                                className="w-full text-left px-4 py-2 text-xs font-bold uppercase tracking-widest text-red-400 hover:text-red-600 transition-all flex items-center gap-2"
                            >
                                <i className="material-icons text-sm">logout</i> Sign Out
                            </button>
                        </div>
                    </aside>

                    {/* Main Content: Order History */}
                    <section className="lg:col-span-3 space-y-10">
                        <header className="flex items-center justify-between">
                            <h2 className="text-2xl font-black text-[#10221c] uppercase tracking-tighter">Acquisition Timeline</h2>
                            <span className="text-[10px] font-bold uppercase tracking-widest text-slate-400 px-3 py-1 bg-slate-100 rounded-full">
                                Last 12 Months
                            </span>
                        </header>

                        {loading ? (
                            <div className="space-y-6">
                                {[1, 2].map(i => <div key={i} className="h-48 bg-slate-100 animate-pulse rounded-lg" />)}
                            </div>
                        ) : orders.length > 0 ? (
                            <div className="space-y-8 relative">
                                {/* Vertical Line for Timeline */}
                                <div className="absolute left-6 top-0 bottom-0 w-0.5 bg-slate-100 -z-0" />

                                {orders.map((order, idx) => (
                                    <div key={order._id} className="relative z-10 pl-16 group">
                                        {/* Timeline Dot */}
                                        <div className={`absolute left-4 top-8 w-4 h-4 rounded-full border-4 border-white shadow-sm ring-2 ${
                                            order.status === 'Delivered' ? 'ring-emerald-500 bg-emerald-500' : 'ring-slate-300 bg-white'
                                        }`} />

                                        <div className="bg-white border border-slate-100 rounded-lg p-6 hover:shadow-xl hover:shadow-slate-200/50 transition-all duration-500">
                                            <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-6">
                                                <div className="space-y-1">
                                                    <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Ordered on {new Date(order.orderDate).toLocaleDateString('en-US', { month: 'long', day: 'numeric', year: 'numeric' })}</p>
                                                    <h3 className="text-xs font-black uppercase text-[#10221c]">Order #{order._id.slice(-8).toUpperCase()}</h3>
                                                </div>
                                                <div className={`px-4 py-1.5 rounded-full text-[9px] font-bold border uppercase tracking-[0.2em] w-fit ${getStatusColor(order.status)}`}>
                                                    {order.status}
                                                </div>
                                            </div>

                                            {/* Products Reveal */}
                                            <div className="flex flex-wrap gap-4 mb-8">
                                                {order.products.map((p, pIdx) => (
                                                    <div key={pIdx} className="group/item relative">
                                                        <div className="w-16 h-20 bg-slate-50 rounded overflow-hidden border border-slate-100 shadow-sm transition-transform group-hover/item:-translate-y-1">
                                                            <img 
                                                                src={p.productId?.images?.[0] || p.productId?.image || 'https://via.placeholder.com/100'} 
                                                                alt="p" 
                                                                className="w-full h-full object-cover" 
                                                            />
                                                        </div>
                                                        <div className="absolute top-0 right-0 -mr-2 -mt-2 bg-[#10221c] text-white text-[8px] font-bold w-4 h-4 rounded-full flex items-center justify-center opacity-0 group-hover/item:opacity-100 transition-opacity">
                                                            {p.quantity}
                                                        </div>
                                                    </div>
                                                ))}
                                            </div>

                                            {/* Status Progress Bar */}
                                            <div className="relative h-1 background-slate-100 rounded-full mb-8 overflow-hidden">
                                                <div className="absolute inset-0 bg-slate-100" />
                                                <div 
                                                    className="absolute inset-y-0 bg-emerald-500 transition-all duration-1000 ease-out" 
                                                    style={{ width: `${(getStatusStep(order.status) + 1) * 25}%` }}
                                                />
                                            </div>

                                            <div className="flex items-center justify-between border-t border-slate-50 pt-4">
                                                <p className="text-[10px] font-bold text-slate-400 uppercase tracking-[0.2em]">Acquisition Total</p>
                                                <p className="text-xl font-black text-[#10221c]">₹{order.totalAmount.toLocaleString()}</p>
                                            </div>
                                        </div>
                                    </div>
                                ))}
                            </div>
                        ) : (
                            /* Empty State - Reusing Cart Animation Logic */
                            <div className="text-center py-20 bg-white rounded-xl border border-dashed border-slate-200">
                                <svg className="w-32 h-32 mx-auto mb-8 opacity-40" viewBox="0 0 200 200">
                                    <circle cx="100" cy="100" r="90" fill="none" stroke="#10221c" strokeWidth="2" strokeDasharray="10 5" />
                                    <g transform="translate(50, 50)">
                                        <rect x="25" y="40" width="50" height="40" fill="none" stroke="#10221c" strokeWidth="4" />
                                        <path d="M 25 40 L 50 15 L 75 40" fill="none" stroke="#10221c" strokeWidth="4" />
                                        <circle cx="50" cy="60" r="10" fill="#10221c" />
                                    </g>
                                </svg>
                                <h3 className="text-lg font-bold text-[#10221c] uppercase tracking-widest mb-2">No Acquisitions Yet</h3>
                                <p className="text-slate-400 text-xs mb-8">Your wardrobe awaits its first luxury piece.</p>
                                <button 
                                    onClick={() => navigate('/')}
                                    className="px-10 py-4 bg-transparent border-2 border-[#10221c] text-[#10221c] text-[10px] font-bold uppercase tracking-[0.3em] hover:bg-[#10221c] hover:text-white transition-all transform active:scale-95"
                                >
                                    Browse Collection
                                </button>
                            </div>
                        )}
                    </section>
                </div>
            </main>
        </div>
    );
};

export default Profile;
